"use client"

import * as React from "react"
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog"

import { cn } from "@/registry/base/lib/utils"
import {
  DIALOG_CONTENT_BASE_CLASSES,
  DIALOG_OVERLAY_CLASSES,
  DialogDragHandle,
} from "@/registry/base/ui/_dialog-shared"
import { Button } from "@/registry/base/ui/button"

function AlertDialog({ ...props }: AlertDialogPrimitive.Root.Props) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
}

function AlertDialogTrigger({ ...props }: AlertDialogPrimitive.Trigger.Props) {
  return (
    <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
  )
}

function AlertDialogPortal({ ...props }: AlertDialogPrimitive.Portal.Props) {
  return (
    <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
  )
}

function AlertDialogOverlay({
  className,
  ...props
}: AlertDialogPrimitive.Backdrop.Props) {
  return (
    <AlertDialogPrimitive.Backdrop
      data-slot="alert-dialog-overlay"
      className={cn(DIALOG_OVERLAY_CLASSES, className)}
      {...props}
    />
  )
}

function AlertDialogContent({
  className,
  size = "default",
  children,
  ...props
}: AlertDialogPrimitive.Popup.Props & {
  size?: "default" | "sm"
}) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Popup
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          DIALOG_CONTENT_BASE_CLASSES,
          "data-[size=default]:sm:max-w-md data-[size=sm]:sm:max-w-xs",
          className
        )}
        {...props}
      >
        <DialogDragHandle />
        {children}
      </AlertDialogPrimitive.Popup>
    </AlertDialogPortal>
  )
}

function AlertDialogHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn(
        "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-6 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-left sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
        "sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-cols-[auto_1fr]",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogFooter({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        "flex flex-col-reverse gap-2 group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogMedia({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-media"
      className={cn(
        "mb-2 inline-flex size-16 items-center justify-center rounded-full bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-8",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn(
        "cn-font-heading text-lg font-medium sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) {
  return (
    <AlertDialogPrimitive.Description
      data-slot="alert-dialog-description"
      className={cn(
        "text-sm text-balance text-muted-foreground md:text-pretty *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        "sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className
      )}
      {...props}
    />
  )
}

function AlertDialogAction({
  className,
  ...props
}: React.ComponentProps<typeof Button>) {
  return (
    <Button
      data-slot="alert-dialog-action"
      className={cn(className)}
      {...props}
    />
  )
}

function AlertDialogCancel({
  className,
  variant = "outline",
  size = "default",
  ...props
}: AlertDialogPrimitive.Close.Props &
  Pick<React.ComponentProps<typeof Button>, "variant" | "size">) {
  return (
    <AlertDialogPrimitive.Close
      data-slot="alert-dialog-cancel"
      className={cn(className)}
      nativeButton
      render={
        <Button data-slot="alert-dialog-cancel" variant={variant} size={size} />
      }
      {...props}
    />
  )
}

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
}

import * as React from "react"

// Shared overlay classes used by both Dialog and AlertDialog
export const DIALOG_OVERLAY_CLASSES = [
  "fixed inset-0 isolate z-50",
  "bg-white/5 backdrop-blur-2xl backdrop-saturate-150",
  "transition-opacity duration-200",
  "data-starting-style:opacity-0",
  "data-ending-style:opacity-0 data-ending-style:duration-100",
  "motion-reduce:transition-none",
].join(" ")

// Shared content positioning + transition classes
// Mobile: full-width bottom sheet sliding up from below
// Desktop (sm+): centered modal scaling up from 0.96
export const DIALOG_CONTENT_BASE_CLASSES = [
  // Positioning — mobile: bottom sheet; desktop: centered via auto margins
  "fixed bottom-0 inset-x-0 z-50 w-full outline-none",
  "sm:inset-0 sm:m-auto sm:h-fit",
  // Appearance
  "bg-popover text-popover-foreground ring-foreground/5 grid gap-6 text-sm ring-1",
  // Padding — safe area on mobile bottom
  "p-6 max-sm:pb-[max(1.5rem,env(safe-area-inset-bottom,0px))]",
  // Border radius — top-only on mobile, all sides on desktop
  "rounded-t-4xl sm:rounded-4xl",
  // Transition origin
  "origin-bottom sm:origin-center",
  // Enter / exit transitions
  "transition-[opacity,transform] duration-[250ms] ease-[cubic-bezier(0.22,1,0.36,1)]",
  // Mobile: slide up from bottom + fade
  "data-starting-style:translate-y-full data-starting-style:opacity-0",
  "data-ending-style:translate-y-full data-ending-style:opacity-0 data-ending-style:duration-150",
  // Desktop: scale + fade (override translate-y to 0)
  "sm:data-starting-style:translate-y-0 sm:data-starting-style:scale-[0.96]",
  "sm:data-ending-style:translate-y-0 sm:data-ending-style:scale-[0.96]",
  "motion-reduce:transition-none",
].join(" ")

// Drag handle — shows only on mobile to indicate swipe-to-dismiss affordance
export function DialogDragHandle() {
  return (
    <div
      aria-hidden
      className="mx-auto mb-2 h-1 w-10 shrink-0 rounded-full bg-foreground/20 sm:hidden"
    />
  )
}
